Dom.Document first = new Dom.Document();
first.load('<root><a>one</a><b>two</b></root>');
Dom.XmlNode firstRoot = first.getRootElement();
Dom.XmlNode b = firstRoot.getChildElement('b', null);
Dom.Document second = new Dom.Document();
second.load('<inserted>three</inserted>');
Dom.XmlNode inserted = second.getRootElement();
Object insertedObject = inserted;
Object referenceObject = b;
System.assertEquals(inserted, firstRoot.insertBefore(insertedObject, referenceObject));
System.assertEquals('inserted', firstRoot.getChildElements()[1].getName());
System.assertEquals('three', firstRoot.getChildElements()[1].getText());
System.assertEquals(true, firstRoot.removeChild(insertedObject));
System.assertEquals('b', firstRoot.getChildElements()[1].getName());
System.assertEquals(true, firstRoot.removeChild(b));
System.assertEquals(1, firstRoot.getChildElements().size());
List<Dom.XmlNodeType> types = Dom.XmlNodeType.values();
System.assertEquals(3, types.size());
System.assertEquals('ELEMENT', String.valueOf(types[0]));
System.assertEquals('TEXT', String.valueOf(types[1]));
System.assertEquals('COMMENT', String.valueOf(types[2]));
System.assertEquals(0, types[0].ordinal());
System.assertEquals(1, types[1].ordinal());
System.assertEquals(2, types[2].ordinal());
System.assertEquals(Dom.XmlNodeType.COMMENT, Dom.XmlNodeType.valueOf('COMMENT'));
System.assertEquals(Dom.XmlNodeType.ELEMENT, Dom.XmlNodeType.valueOf('ELEMENT'));
first = null; firstRoot = null; b = null; second = null; inserted = null; insertedObject = null; referenceObject = null; types = null;

